def find_index(document: Document, prefix: str) -> int:
    for index, paragraph in enumerate(document.paragraphs):
        if paragraph.text.strip().startswith(prefix):
            return index
    raise ValueError(f"Cannot find section: {prefix}")


def remove_paragraph(paragraph) -> None:
    element = paragraph._element
    element.getparent().remove(element)


def replace_section(document: Document, start_prefix: str, end_prefix: str, new_paragraphs: list[str]) -> None:
    start = find_index(document, start_prefix)
    end = find_index(document, end_prefix)
    for paragraph in list(document.paragraphs[start:end]):
        remove_paragraph(paragraph)
    target = document.paragraphs[find_index(document, end_prefix)]
    for text in new_paragraphs:
        p = target.insert_paragraph_before(text)
        if text == new_paragraphs[0]:
            if text in {"АННОТАЦИЯ", "ВВЕДЕНИЕ", "ЗАКЛЮЧЕНИЕ"} or text.startswith("ГЛАВА"):
                try:
                    p.style = "Heading 1"
                except KeyError:
                    pass
            elif text[:1].isdigit():
                try:
                    p.style = "Heading 2"
                except KeyError:
                    pass


def cleanup_language(document: Document) -> None:
    replacements = {
        "security-relevant сценариями": "сценариями, значимыми с точки зрения безопасности",
        "security-relevant сценариям": "сценариям, значимым с точки зрения безопасности",
        "security-relevant сценариев": "сценариев, значимых с точки зрения безопасности",
        "security-relevant сценарии": "сценарии, значимые с точки зрения безопасности",
        "security-relevant сценариев.": "сценариев, значимых с точки зрения безопасности.",
        "ML-подходи": "ML-подходы",
        "baseline-эвристики": "базовой эвристики",
        "baseline-эвристикой": "базовой эвристикой",
        "baseline-эвристика": "базовая эвристика",
        "baseline нашел": "базовая эвристика нашла",
        "baseline обнаружил": "базовая эвристика обнаружила",
        "baseline по времени": "базовая эвристика по времени",
        "для baseline": "для базовой эвристики",
        "для базовая эвристика": "для базовой эвристики",
        "базовая эвристика -": "базовая эвристика нашла",
        "pipeline": "пайплайн",
    }
    for paragraph in document.paragraphs:
        text = paragraph.text
        new_text = text
        for old, new in replacements.items():
            new_text = new_text.replace(old, new)
        if new_text != text:
            paragraph.text = new_text


def main() -> int:
    parser = argparse.ArgumentParser(description="Polish dissertation DOCX academic style and logic.")
    parser.add_argument("--source", default=SOURCE_DOCX)
    parser.add_argument("--output", default="scripts/out/Диссертация_scientific_polished.docx")
    args = parser.parse_args()

    document = Document(args.source)
    replace_section(document, "АННОТАЦИЯ", "ВВЕДЕНИЕ", ANNOTATION)
    replace_section(document, "ВВЕДЕНИЕ", "ГЛАВА 1.", INTRODUCTION)
    replace_section(document, "1.7.", "ГЛАВА 2.", CHAPTER1_CONCLUSION)
    replace_section(document, "2.11.", "ГЛАВА 3.", CHAPTER2_CONCLUSION)
    replace_section(document, "3.10.", "ЗАКЛЮЧЕНИЕ", CHAPTER3_CONCLUSION)
    replace_section(document, "ЗАКЛЮЧЕНИЕ", "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ", CONCLUSION)
    cleanup_language(document)

    output = Path(args.output)
    output.parent.mkdir(parents=True, exist_ok=True)
    document.save(output)
    print(f"Polished DOCX: {output.as_posix()}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
